<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo htmlspecialchars($browserTitle, ENT_QUOTES, 'UTF-8'); ?></title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#20242a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.wrap{width:92%;max-width:420px;margin:32px auto;padding:26px 22px 30px;background:#fff;border-radius:8px;box-shadow:0 6px 24px rgba(0,0,0,.08);text-align:center}h1{margin:0 0 12px;font-size:22px}.icon{width:20px;height:20px;vertical-align:-3px;margin-right:6px}.amount{margin-bottom:14px;color:#e64340;font-size:30px;font-weight:700}.qr{position:relative;width:250px;height:250px;margin:16px auto;padding:10px;border:1px solid #e7eaee;background:#fff}.qr-inner{width:230px;height:230px;display:flex;align-items:center;justify-content:center;overflow:hidden}.qr-inner img,.qr-inner canvas{max-width:230px;max-height:230px}.mask{display:none;position:absolute;inset:0;z-index:2;align-items:center;justify-content:center;flex-direction:column;background:rgba(20,24,30,.82);color:#fff;font-size:18px;font-weight:600}.mask small{margin-top:8px;font-size:13px;font-weight:400}.count{margin:12px 0;color:#e64340;font-size:16px}.meta{margin:8px 0 14px;color:#8a919b;font-size:13px;line-height:1.8}.hint{color:#8a919b;font-size:14px;line-height:1.7}.error{margin:26px 0;color:#d93025;line-height:1.7}</style></head><body><main class="wrap"><h1><?php if($paymentIcon!==''): ?><img class="icon" src="<?php echo htmlspecialchars($paymentIcon,ENT_QUOTES,'UTF-8'); ?>" alt=""><?php endif; echo htmlspecialchars($title,ENT_QUOTES,'UTF-8'); ?></h1><div class="amount">￥<?php echo htmlspecialchars((string)$order['realmoney'],ENT_QUOTES,'UTF-8'); ?></div><?php if($error_msg!==''): ?><div class="error"><?php echo htmlspecialchars($error_msg,ENT_QUOTES,'UTF-8'); ?></div><?php else: ?><div class="qr"><div class="qr-inner" id="qr"></div><div class="mask" id="mask"><span>二维码已失效</span><small>订单已超时，请重新发起支付</small></div></div><div class="count">支付剩余时间：<b id="timer">--:--</b></div><div class="meta"><div>订单号：<?php echo htmlspecialchars((string)$order['trade_no'],ENT_QUOTES,'UTF-8'); ?></div><div>订单创建时间：<?php echo htmlspecialchars((string)$order['addtime'],ENT_QUOTES,'UTF-8'); ?></div></div><div class="hint"><?php echo htmlspecialchars($payHint, ENT_QUOTES, 'UTF-8'); ?><br>支付完成后页面会自动跳转</div><?php endif; ?></main><script src="<?php echo $cdnpublic; ?>jquery/1.12.4/jquery.min.js"></script><script src="<?php echo $cdnpublic; ?>jquery.qrcode/1.0/jquery.qrcode.min.js"></script><?php if($error_msg===''): ?><script>(function(){var code=<?php echo json_encode($code_url,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,left=<?php echo (int)$paytime; ?>,timer=document.getElementById('timer'),mask=document.getElementById('mask');if(code.indexOf('data:image/')===0){var i=document.createElement('img');i.src=code;i.alt='支付二维码';document.getElementById('qr').appendChild(i)}else{$('#qr').qrcode({text:code,width:230,height:230,typeNumber:-1})}function tick(){if(left<=0){mask.style.display='flex';timer.textContent='00:00';return}var m=Math.floor(left/60),s=left%60;timer.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;left--}tick();setInterval(tick,1000);function check(){$.getJSON('/getshop.php',{trade_no:<?php echo json_encode($order['trade_no']); ?>},function(d){if(d&&d.code===1)location.href=d.backurl;else if(left>0)setTimeout(check,2000)}).fail(function(){if(left>0)setTimeout(check,3000)})}setTimeout(check,1800)}())</script><?php endif; ?></body></html>
